import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class QuickAddService {

    /** The person the claim was added to, and the claim. */
    public record Added(Person person, Claim claim) {
    }

    private final PersonRepository people;
    private final PersonService personService;
    private final ClaimService claimService;
    private final SheetSettingRepository settings;

    public QuickAddService(PersonRepository people, PersonService personService, ClaimService claimService,
            SheetSettingRepository settings) {
        this.people = people;
        this.personService = personService;
        this.claimService = claimService;
        this.settings = settings;
    }

    /** Add a draft claim of the amount, dated the sheet's entry date (else its today) with an empty note, to the person of
     *  that name, adding the person with the sheet's default grade first when no one on the sheet has it. One change: a
     *  refused claim rolls back the person added for it, and writes nothing. */
    @Transactional
    public Added add(String sheetId, String user, String name, BigDecimal amount) {
        Person person = people.findByNameOrAlias(sheetId, Person.keyOf(name))
                .orElseGet(() -> personService.add(sheetId, user, name,
                        SettingService.defaultGradeOf(settings, sheetId), null));
        Claim claim = claimService.add(sheetId, user, person.getId(), amount, null, "", null, null, null);
        return new Added(person, claim);
    }
}
#!/usr/bin/env bash
# Build, start the whole app, run the Playwright specs present in e2e/specs, then stop.
set -euo pipefail
cd "$(dirname "$0")/.."

export PORT="${PORT:-3000}"
export BASE_URL="http://localhost:${PORT}"
# Known audit file, shared by the app (bin/start) and the specs (support/audit.ts). Absolute.
export AUDIT_FILE="${AUDIT_FILE:-$PWD/.run/audit.log}"

# Refuse to run against a server that is not ours: an app left running on $PORT (an earlier
# bin/start that was never stopped, another sandbox) would take the tests and fail them all.
if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then
  echo "bin/e2e: something is already serving on port ${PORT}; stop it (bin/stop) or set PORT to a free port" >&2
  exit 2
fi

bin/build
bin/start
cleanup() { bin/stop || true; }
trap cleanup EXIT

# Wait for readiness (Actuator health), then run the Playwright specs against BASE_URL. A loaded
# machine can take minutes to bring the JVM up; running the specs before it is ready fails every
# one of them for no reason, so wait long and fail loudly rather than run against nothing.
ready=0
for i in $(seq 1 300); do
  if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then ready=1; break; fi
  sleep 1
done
if [ "$ready" != 1 ]; then
  echo "bin/e2e: the app did not become healthy on port ${PORT} within 300s; see .run/app.log" >&2
  exit 2
fi

# Install deps + the Chromium browser (both cached after first run), then run the specs.
( cd e2e && npm ci --silent && npx --yes playwright install chromium && npx playwright test )

